static const size_t gKBModelCount = 198;

static inline int HammingDistance(uint64_t a, uint64_t b)
{
#if defined(__GNUC__) || defined(__clang__)
	return __builtin_popcountll(a ^ b);
#else
	uint64_t v = a ^ b;
	int c = 0;
	while (v) { c += (v & 1); v >>= 1; }
	return c;
#endif
}

size_t lcKBCatalog::GetModelCount()
{
	return gKBModelCount;
}

const lcKBModelEntry* lcKBCatalog::GetModel(size_t Index)
{
	if (Index < gKBModelCount)
		return &gKBModels[Index];
	return nullptr;
}

const lcKBModelEntry* lcKBCatalog::FindBestMatch(const QString& Prompt, int TargetPieces, int* OutScore)
{
	QString Lower = Prompt.toLower().trimmed();
	QStringList Words = Lower.split(QRegExp("[\\s,;:.!?-]+"), QString::SkipEmptyParts);
	QSet<QString> WordSet = Words.toSet();

	const lcKBModelEntry* BestModel = nullptr;
	int BestScore = -1;

	for (size_t i = 0; i < gKBModelCount; ++i)
	{
		const lcKBModelEntry& Entry = gKBModels[i];
		int Score = 0;

		QString EntryName = QString::fromUtf8(Entry.Name).toLower();
		QStringList NameWords = EntryName.split(QRegExp("[\\s,;:.!?-]+"), QString::SkipEmptyParts);
		QString EntryTags = QString::fromUtf8(Entry.Tags).toLower();
		QStringList TagWords = EntryTags.split(' ', QString::SkipEmptyParts);
		QString EntryCats = QString::fromUtf8(Entry.Categories).toLower();
		QStringList CatList = EntryCats.split(' ', QString::SkipEmptyParts);

		// Direct title match
		if (Lower.contains(EntryName))
			Score += 160;

		// Name word overlap
		for (const QString& W : NameWords)
		{
			if (W.length() > 2 && WordSet.contains(W))
				Score += 45;
		}

		// Tag overlap
		for (const QString& T : TagWords)
		{
			if (T.length() > 2 && WordSet.contains(T))
				Score += 18;
		}

		// Semantic distinctions and priority boosts
		if (WordSet.contains("pickup") || WordSet.contains("pick-up"))
		{
			if (TagWords.contains("pickup")) Score += 130;
		}
		if (WordSet.contains("tow") && TagWords.contains("tow"))
			Score += 130;
		if (WordSet.contains("tractor") && CatList.contains("heavy_machinery"))
			Score += 130;
		if (WordSet.contains("helicopter") && (TagWords.contains("helicopter") || CatList.contains("aircraft")))
			Score += 120;
		if (WordSet.contains("dragster") && TagWords.contains("dragster"))
			Score += 130;
		if (WordSet.contains("speedboat") && TagWords.contains("speedboat"))
			Score += 120;
		if (WordSet.contains("police") && TagWords.contains("police"))
			Score += 100;
		if (WordSet.contains("fire") && TagWords.contains("fire"))
			Score += 100;
		if (WordSet.contains("x-wing") && TagWords.contains("x-wing"))
			Score += 150;
		if (WordSet.contains("destroyer") && TagWords.contains("destroyer"))
			Score += 150;
		if (WordSet.contains("lighthouse") && TagWords.contains("lighthouse"))
			Score += 130;
		if ((WordSet.contains("empire") || WordSet.contains("state")) && TagWords.contains("empire"))
			Score += 130;
		if (WordSet.contains("buggy") && TagWords.contains("buggy"))
			Score += 90;
		if (WordSet.contains("ferrari") || WordSet.contains("f40"))
		{
			if (EntryName.contains("ferrari") || TagWords.contains("ferrari")) Score += 140;
		}
		if (WordSet.contains("super") && WordSet.contains("chief"))
		{
			if (EntryName.contains("super chief")) Score += 160;
		}
		if (WordSet.contains("locomotive") || WordSet.contains("engine"))
		{
			if (EntryName.contains("locomotive") || CatList.contains("train_rail")) Score += 100;
		}
		if (WordSet.contains("white") && WordSet.contains("house"))
		{
			if (EntryName.contains("white house")) Score += 170;
		}
		if (WordSet.contains("eiffel"))
		{
			if (EntryName.contains("eiffel")) Score += 170;
		}
		if (WordSet.contains("big") && WordSet.contains("ben"))
		{
			if (EntryName.contains("big ben")) Score += 170;
		}
		if (WordSet.contains("pisa"))
		{
			if (EntryName.contains("pisa")) Score += 170;
		}
		if (WordSet.contains("sydney") || WordSet.contains("opera"))
		{
			if (EntryName.contains("sydney")) Score += 160;
		}
		if (WordSet.contains("brandenburg"))
		{
			if (EntryName.contains("brandenburg")) Score += 170;
		}
		if (WordSet.contains("truck") && CatList.contains("truck_pickup"))
			Score += 40;
		if (WordSet.contains("car") && (CatList.contains("car_civilian") || CatList.contains("car_racing")))
			Score += 30;
		if (WordSet.contains("train") && CatList.contains("train_rail"))
			Score += 50;
		if (WordSet.contains("space") && CatList.contains("spacecraft"))
			Score += 40;
		if (WordSet.contains("house") && CatList.contains("building_town"))
			Score += 40;

		// Piece Count Conditioning
		if (TargetPieces > 0 && Score > 15)
		{
			int Diff = std::abs(Entry.PieceCount - TargetPieces);
			if (Diff <= std::max(15, TargetPieces / 5))
				Score += 55;
			else if (Diff <= std::max(30, TargetPieces / 3))
				Score += 30;
			else if (Diff <= std::max(60, TargetPieces / 2))
				Score += 10;
			else if (Diff > TargetPieces)
				Score -= 25;
		}

		if (Score > BestScore)
		{
			BestScore = Score;
			BestModel = &Entry;
		}
	}

	if (OutScore)
		*OutScore = BestScore;

	// Threshold for retrieval vs procedural fallback
	return (BestScore >= 25) ? BestModel : nullptr;
}

const lcKBModelEntry* lcKBCatalog::FindBestVisualMatch(uint64_t VisualHash, int DominantColor, int TargetPieces, int* OutScore)
{
	if (VisualHash == 0 && DominantColor < 0)
	{
		if (OutScore) *OutScore = 0;
		return nullptr;
	}

	const lcKBModelEntry* BestModel = nullptr;
	int BestScore = -1;

	for (size_t i = 0; i < gKBModelCount; ++i)
	{
		const lcKBModelEntry& Entry = gKBModels[i];
		int Score = 0;

		if (VisualHash != 0 && Entry.VisualHash != 0)
		{
			int Dist = HammingDistance(VisualHash, Entry.VisualHash);
			Score += std::max(0, (32 - Dist) * 4);
		}

		if (DominantColor >= 0)
		{
			if (Entry.DominantColor == DominantColor)
				Score += 35;
			else if (Entry.SecondaryColor == DominantColor)
				Score += 15;
		}

		if (TargetPieces > 0 && Score > 15)
		{
			int Diff = std::abs(Entry.PieceCount - TargetPieces);
			if (Diff <= std::max(15, TargetPieces / 4))
				Score += 35;
			else if (Diff <= std::max(30, TargetPieces / 2))
				Score += 15;
		}

		if (Score > BestScore)
		{
			BestScore = Score;
			BestModel = &Entry;
		}
	}

	if (OutScore)
		*OutScore = BestScore;

	return (BestScore >= 35) ? BestModel : nullptr;
}

std::vector<const lcKBModelEntry*> lcKBCatalog::Search(const QString& Query, int MaxResults)
{
	std::vector<const lcKBModelEntry*> Results;
	QString Lower = Query.toLower().trimmed();
	if (Lower.isEmpty()) return Results;

	for (size_t i = 0; i < gKBModelCount; ++i)
	{
		const lcKBModelEntry& Entry = gKBModels[i];
		QString EntryName = QString::fromUtf8(Entry.Name).toLower();
		QString EntryTags = QString::fromUtf8(Entry.Tags).toLower();

		if (EntryName.contains(Lower) || EntryTags.contains(Lower))
		{
			Results.push_back(&Entry);
			if (static_cast<int>(Results.size()) >= MaxResults)
				break;
		}
	}

	return Results;
}
